// Live lens control surface of the Cinematic Camera component.//// Other plugins (CryPhoneTracker) drive the lens without linking against CinematicCamera:// they resolve CryGetCinematicCameraOptics from the already loaded CinematicCamera.dll and// simply get nullptr back when that plugin is not part of the project.#pragma oncestruct IEntity;struct ICinematicCameraOptics{	virtual ~ICinematicCameraOptics() {}	virtual void SetFocalLength(float millimetres) = 0;	virtual void SetAperture(float fNumber) = 0;	virtual void SetFocusDistance(float metres) = 0;	virtual void SetEVCompensation(float ev) = 0;	virtual void SetISO(float iso) = 0;	virtual void SetDepthOfFieldEnabled(bool enable) = 0;	virtual void SetExposureEnabled(bool enable) = 0;	virtual float GetFocalLength() const = 0;	virtual float GetAperture() const = 0;	virtual float GetFocusDistance() const = 0;	virtual float GetEVCompensation() const = 0;	virtual float GetISO() const = 0;};//! Name of the C entry point exported by CinematicCamera.dll.#define CINEMATIC_CAMERA_OPTICS_ENTRY "CryGetCinematicCameraOptics"//! Signature of that entry point: returns the optics interface of the cinematic camera//! component on pEntity, or nullptr when the entity carries no such component.typedef ICinematicCameraOptics* (* TGetCinematicCameraOpticsFn)(IEntity* pEntity);//! Entry point returning the entity of the currently active cinematic camera (nullptr when a//! non-cinematic camera owns the view). Lets a controller (the phone tracker) follow whichever//! camera the operator switched to instead of staying glued to one entity.#define CINEMATIC_CAMERA_ACTIVE_ENTITY_ENTRY "CryGetActiveCinematicCameraEntity"typedef IEntity* (* TGetActiveCinematicCameraEntityFn)();//! Entry point activating the cinematic camera whose Slot property equals slot (1-9).//! Returns false when no camera carries that slot.#define CINEMATIC_CAMERA_ACTIVATE_SLOT_ENTRY "CryActivateCinematicCameraSlot"typedef bool (* TActivateCinematicCameraSlotFn)(int slot);